begin;
insert into auth.users(id,email) values('c6000000-0000-4000-8000-000000000001','manager@example.invalid'),('c6000000-0000-4000-8000-000000000002','farmer@example.invalid'),('c6000000-0000-4000-8000-000000000003','farmer@example.invalid'),('c6000000-0000-4000-8000-000000000004','customer@example.invalid');
insert into public.profiles(id,display_name,account_role) select id,'Harvest QA',split_part(email,'@',1) from auth.users;
insert into public.fpos(id,name,location) values('d6000000-0000-4000-8000-000000000001','QA Farm','Test'),('d6000000-0000-4000-8000-000000000002','Other FPO','Test');
insert into public.memberships(fpo_id,user_id,role,status) values('d6000000-0000-4000-8000-000000000001','c6000000-0000-4000-8000-000000000001','manager','active'),('d6000000-0000-4000-8000-000000000001','c6000000-0000-4000-8000-000000000002','farmer','active'),('d6000000-0000-4000-8000-000000000002','c6000000-0000-4000-8000-000000000002','farmer','pending'),('d6000000-0000-4000-8000-000000000001','c6000000-0000-4000-8000-000000000003','farmer','pending');
insert into private.wa_links(user_id,phone) values('c6000000-0000-4000-8000-000000000001','919000006001'),('c6000000-0000-4000-8000-000000000002','919000006002'),('c6000000-0000-4000-8000-000000000003','919000006003'),('c6000000-0000-4000-8000-000000000004','919000006004');
do $qa$ begin
 if has_function_privilege('authenticated','public.wa_harvest_command(text,text)','execute') or has_function_privilege('anon','public.wa_harvest_command(text,text)','execute') or has_table_privilege('authenticated','private.wa_harvest_drafts','select') then raise exception 'FAIL privileges';end if;
end $qa$;
set local role service_role;
do $qa$ declare r text; begin
 if public.wa_harvest_command('919000006009','FPOS') not like 'Link your%' then raise exception 'FAIL unlinked';end if;
 if public.wa_harvest_command('919000006001','FPOS') not like '%Farmer account%' or public.wa_harvest_command('919000006004','FPOS') not like '%Farmer account%' then raise exception 'FAIL role';end if;
 if public.wa_harvest_command('919000006004','HI') not like '%SHOP%' or public.wa_harvest_command('919000006002','HI') not like '%FPOS%' then raise exception 'FAIL menu';end if;
 if public.wa_harvest_command('919000006003','FPOS') not like 'No approved%' then raise exception 'FAIL pending membership';end if;
 r:=public.wa_harvest_command('919000006002','FPOS');
 if r not like '%QA Farm%' or r like '%Other FPO%' then raise exception 'FAIL FPO list';end if;
 if public.wa_harvest_command('919000006002','HARVEST 1 | Tomatoes | 0 | 2026-01-01') not like 'Enter a crop%' then raise exception 'FAIL quantity';end if;
 if public.wa_harvest_command('919000006002','HARVEST 1 | Tomatoes | 1 | 2026-02-30') not like 'Enter a valid%' then raise exception 'FAIL date';end if;
 if public.wa_harvest_command('919000006002','HARVEST 1 | Tomatoes | 1 | 9999-01-01') not like 'Harvest date cannot%' then raise exception 'FAIL future';end if;
 r:=public.wa_harvest_command('919000006002','HARVEST 1 | Red Onions | 12.345 | 2026-01-01');
 if r not like '%Red Onions | 12.345 kg%' then raise exception 'FAIL preview %',r;end if;
 perform set_config('qa.harvest',substring(r from 'SUBMIT ([0-9a-f-]{36})'),true);
end $qa$;
reset role;
do $qa$ begin if exists(select 1 from public.harvests) then raise exception 'FAIL preview submitted';end if;end $qa$;
set local role service_role;
do $qa$ begin
 if public.wa_harvest_command('919000006003','SUBMIT '||current_setting('qa.harvest')) not like 'Draft expired%' then raise exception 'FAIL other sender';end if;
 if public.wa_harvest_command('919000006002','SUBMIT '||current_setting('qa.harvest')) not like 'Harvest submitted!%' then raise exception 'FAIL submit';end if;
 if public.wa_harvest_command('919000006002','SUBMIT '||current_setting('qa.harvest')) not like 'Harvest already submitted%' then raise exception 'FAIL duplicate';end if;
 if public.wa_harvest_command('919000006003','HARVESTS '||current_setting('qa.harvest')) not like 'No matching%' then raise exception 'FAIL status isolation';end if;
end $qa$;
reset role;
do $qa$ begin if (select count(*) from public.harvests)<>1 or exists(select 1 from public.inventory_lots) or not exists(select 1 from public.harvests where id=current_setting('qa.harvest')::uuid and crop='Red Onions' and quantity_kg=12.345 and status='pending' and photo_path is null) then raise exception 'FAIL pending stock';end if;end $qa$;
set local role authenticated;
select set_config('request.jwt.claim.sub','c6000000-0000-4000-8000-000000000001',true);
select public.review_harvest(current_setting('qa.harvest')::uuid,'A',3000,true,'');
reset role;
set local role service_role;
do $qa$ begin if public.wa_harvest_command('919000006002','HARVESTS '||current_setting('qa.harvest')) not like '%Status: approved%Grade: A%' then raise exception 'FAIL approved status';end if;
 perform set_config('qa.second',substring(public.wa_harvest_command('919000006002','HARVEST 1 | Cabbage | 5 | 2026-01-01') from 'SUBMIT ([0-9a-f-]{36})'),true);
end $qa$;
reset role;
update private.wa_harvest_drafts set draft_expires=clock_timestamp()-interval '1 second' where user_id='c6000000-0000-4000-8000-000000000002';
set local role service_role;
do $qa$ begin if public.wa_harvest_command('919000006002','SUBMIT '||current_setting('qa.second')) not like 'Draft expired%' then raise exception 'FAIL expiry';end if;
 perform set_config('qa.third',substring(public.wa_harvest_command('919000006002','HARVEST 1 | Cabbage | 5 | 2026-01-01') from 'SUBMIT ([0-9a-f-]{36})'),true);
end $qa$;
reset role;
update public.memberships set status='rejected' where user_id='c6000000-0000-4000-8000-000000000002' and fpo_id='d6000000-0000-4000-8000-000000000001';
set local role service_role;
do $qa$ begin if public.wa_harvest_command('919000006002','SUBMIT '||current_setting('qa.third')) not like 'FPO membership is no longer%' then raise exception 'FAIL revoked membership';end if;end $qa$;
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','c6000000-0000-4000-8000-000000000002',true);
select public.wa_unlink();
reset role;
do $qa$ begin if exists(select 1 from private.wa_harvest_drafts where user_id='c6000000-0000-4000-8000-000000000002') or (select count(*) from public.harvests)<>1 or not exists(select 1 from public.inventory_lots where harvest_id=current_setting('qa.harvest')::uuid and available_kg=12.345 and grade='A') then raise exception 'FAIL unlink cleanup or stock';end if;end $qa$;
select 'PASS: farmer role, approved FPO, validation, explicit submission, duplicate protection, status isolation, approval inventory, expiry, membership recheck and unlink cleanup' result;
rollback;